#!/usr/bin/env python3

import html
import json
import os
import re
import shutil
import subprocess
from pathlib import Path

# ============================================================
# Configuration
# ============================================================

ROOT = Path.cwd()
SITE = ROOT / "_site"

REPO = os.environ.get("GITHUB_REPOSITORY", "")
REPO_NAME = REPO.split("/", 1)[1] if "/" in REPO else ROOT.name

TEMP_DIR = Path(os.environ.get("RUNNER_TEMP", "/tmp"))
MERGED_PRS_FILE = TEMP_DIR / "merged-prs.json"

# Bootstrap is downloaded by pages.yml into this directory.
BOOTSTRAP_DIR = SITE / "assets"
BOOTSTRAP_CSS = BOOTSTRAP_DIR / "bootstrap.min.css"
BOOTSTRAP_JS = BOOTSTRAP_DIR / "bootstrap.bundle.min.js"

# Files which should never be rendered as source files.
EXCLUDED_FILES = {
  ".git",
  ".github",
  "_site",
  "merged-prs.json",
  ".DS_Store",
}

# File extensions which are useful to display.
SOURCE_EXTENSIONS = {
  ".java",
  ".xml",
  ".yml",
  ".yaml",
  ".properties",
  ".md",
  ".txt",
  ".json",
  ".gradle",
  ".kts",
}

# Search is deliberately restricted to Java files.
SEARCH_EXTENSIONS = {".java"}

CONTEXT_LINES = 2
MAX_MATCH_LINES_PER_FILE = 10


# ============================================================
# Utility functions
# ============================================================

def run(command, cwd=None):
  """Run a command and return stdout."""
  result = subprocess.run(
    command,
    cwd=cwd,
    check=True,
    text=True,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
  )
  return result.stdout.strip()


def git(command):
  """Run a git command in the repository."""
  return run(["git"] + command, cwd=ROOT)


def safe_text(value):
  if value is None:
    return ""
  return str(value)


def html_escape(value):
  return html.escape(safe_text(value), quote=True)


def normalize_path(path):
  return str(path).replace("\\", "/")


def is_excluded(path):
  """
  Return True if a repository path contains a directory/file
  which should not be published.
  """
  parts = Path(path).parts

  for part in parts:
    if part in EXCLUDED_FILES:
      return True

  return False


def is_source_file(path):
  if is_excluded(path):
    return False

  return Path(path).suffix.lower() in SOURCE_EXTENSIONS


def is_searchable_file(path):
  if is_excluded(path):
    return False

  return Path(path).suffix.lower() in SEARCH_EXTENSIONS


def read_text_file(path):
  try:
    return path.read_text(encoding="utf-8")
  except UnicodeDecodeError:
    return path.read_text(encoding="utf-8", errors="replace")


def write_text(path, content):
  path.parent.mkdir(parents=True, exist_ok=True)
  path.write_text(content, encoding="utf-8")


def clean_site():
  if SITE.exists():
    shutil.rmtree(SITE)

  SITE.mkdir(parents=True)


# ============================================================
# Git / PR information
# ============================================================

def load_merged_prs():
  """
  Read merged PR metadata generated by pages.yml.

  Expected JSON:
  [
    {
      "number": 12,
      "title": "...",
      "mergeCommit": {
        "oid": "..."
      },
      "mergedAt": "..."
    }
  ]
  """

  if not MERGED_PRS_FILE.exists():
    print("No merged-prs.json found.")
    return []

  try:
    data = json.loads(read_text_file(MERGED_PRS_FILE))
  except json.JSONDecodeError as exc:
    print(f"WARNING: Could not parse {MERGED_PRS_FILE}: {exc}")
    return []

  if not isinstance(data, list):
    return []

  result = []

  for pr in data:
    if not isinstance(pr, dict):
      continue

    number = pr.get("number")
    title = pr.get("title") or f"Pull Request #{number}"

    merge_commit = pr.get("mergeCommit") or {}
    sha = merge_commit.get("oid")

    merged_at = pr.get("mergedAt") or ""

    if not number or not sha:
      continue

    result.append(
      {
        "number": int(number),
        "title": title,
        "sha": sha,
        "mergedAt": merged_at,
      }
    )

  # Newest merged PR first.
  result.sort(
    key=lambda item: item.get("mergedAt", ""),
    reverse=True,
  )

  return result


def get_main_commit():
  return git(["rev-parse", "HEAD"])


# ============================================================
# Source snapshot handling
# ============================================================

def create_snapshot_from_commit(commit, destination):
  """
  Create a complete repository snapshot for a git commit.

  git archive is used instead of checking out the commit, so the
  generator itself can continue running from the current checkout.
  """

  if destination.exists():
    shutil.rmtree(destination)

  destination.mkdir(parents=True)

  archive = subprocess.Popen(
    ["git", "archive", commit],
    cwd=ROOT,
    stdout=subprocess.PIPE,
  )

  try:
    subprocess.run(
      ["tar", "-x", "-C", str(destination)],
      stdin=archive.stdout,
      check=True,
    )
  finally:
    if archive.stdout:
      archive.stdout.close()

  return destination


# ============================================================
# Bootstrap
# ============================================================

def copy_bootstrap():
  """
  Bootstrap is downloaded by pages.yml.

  Keeping it locally in the generated Pages site means learners
  do not need access to jsdelivr.net or another external CDN.
  """

  if not BOOTSTRAP_CSS.exists():
    raise RuntimeError(
      f"Bootstrap CSS not found: {BOOTSTRAP_CSS}"
    )

  if not BOOTSTRAP_JS.exists():
    raise RuntimeError(
      f"Bootstrap JS not found: {BOOTSTRAP_JS}"
    )


# ============================================================
# URL handling
# ============================================================

def site_base():
  """
  GitHub Pages project sites are normally published below:

      /repository-name/

  This is important because the generated site is not necessarily
  hosted at the domain root.
  """

  return "/" + REPO_NAME.strip("/") + "/"


def version_base(version_type, pr_number=None):
  base = site_base()

  if version_type == "main":
    return base

  if version_type == "pr":
    return base + f"pr/{pr_number}/"

  raise ValueError(f"Unknown version type: {version_type}")


def relative_url_from_version(version_base_url, path):
  return version_base_url + normalize_path(path)


# ============================================================
# Syntax highlighting
# ============================================================

def get_lexer_for_file(path):
  try:
    from pygments.lexers import (
      JavaLexer,
      XmlLexer,
      YamlLexer,
      JsonLexer,
      PropertiesLexer,
      MarkdownLexer,
      TextLexer,
    )
  except ImportError:
    return None

  suffix = Path(path).suffix.lower()

  if suffix == ".java":
    return JavaLexer()

  if suffix == ".xml":
    return XmlLexer()

  if suffix in {".yml", ".yaml"}:
    return YamlLexer()

  if suffix == ".json":
    return JsonLexer()

  if suffix == ".properties":
    return PropertiesLexer()

  if suffix == ".md":
    return MarkdownLexer()

  return TextLexer()


def highlight_source(path, content):
  """
  Highlight source using Pygments.

  If Pygments cannot identify a lexer, plain escaped text is used.
  """

  try:
    from pygments import highlight
    from pygments.formatters import HtmlFormatter
  except ImportError:
    return html_escape(content)

  lexer = get_lexer_for_file(path)

  if lexer is None:
    return html_escape(content)

  formatter = HtmlFormatter(nowrap=True)

  highlighted = highlight(
    content,
    lexer,
    formatter,
  )

  return highlighted


# ============================================================
# Markdown
# ============================================================

def render_markdown(content):
  try:
    import markdown

    return markdown.markdown(
      content,
      extensions=[
        "fenced_code",
        "tables",
        "toc",
      ],
    )

  except ImportError:
    return (
      "<pre class=\"p-3 bg-body-tertiary rounded\">"
      + html_escape(content)
      + "</pre>"
    )


# ============================================================
# Directory tree
# ============================================================

def build_tree(root):
  """
  Return a nested dictionary representing the source tree.

  Directories:
      {
        "src": {
           "main": {
              "java": {
                  "__files__": [...]
              }
           }
        }
      }
  """

  tree = {}

  for path in sorted(root.rglob("*")):
    if not path.is_file():
      continue

    relative = path.relative_to(root)
    relative_string = normalize_path(relative)

    if is_excluded(relative_string):
      continue

    if not is_source_file(relative_string):
      continue

    parts = list(relative.parts)

    current = tree

    for directory in parts[:-1]:
      current = current.setdefault(directory, {})

    current.setdefault("__files__", []).append(parts[-1])

  return tree


def tree_has_content(node):
  for key, value in node.items():
    if key == "__files__":
      if value:
        return True
    elif isinstance(value, dict) and tree_has_content(value):
      return True

  return False


def render_tree_node(
  node,
  version_base_url,
  parent_id="tree-root",
  level=0,
):
  """
  Render a Bootstrap collapsible directory tree.

  The generated HTML intentionally uses normal strings instead
  of Python f-strings.
  """

  pieces = []

  directories = sorted(
    key for key in node.keys()
    if key != "__files__"
  )

  files = sorted(node.get("__files__", []))

  for directory in directories:
    child = node[directory]

    if not tree_has_content(child):
      continue

    safe_id = re.sub(
      r"[^A-Za-z0-9_-]",
      "-",
      parent_id + "-" + directory,
    )

    child_html = render_tree_node(
      child,
      version_base_url,
      parent_id=safe_id,
      level=level + 1,
    )

    pieces.append(
      '<div class="tree-directory mb-1">'
      '<button '
      'class="btn btn-sm btn-toggle w-100 text-start" '
      'type="button" '
      'data-bs-toggle="collapse" '
      'data-bs-target="#'
      + html_escape(safe_id)
      + '" '
        'aria-expanded="'
      + ("true" if level == 0 else "false")
      + '">'
        '<span class="tree-icon">▸</span> '
      + html_escape(directory)
      + '</button>'
        '<div id="'
      + html_escape(safe_id)
      + '" class="collapse '
      + ("show" if level == 0 else "")
      + '">'
        '<div class="ms-3 ps-2 border-start">'
      + child_html
      + "</div>"
        "</div>"
        "</div>"
    )

  for filename in files:
    relative_path = find_relative_file_path(
      node,
      filename,
      prefix=[],
    )

    # The helper above cannot determine the full path from this
    # local node alone. File links are therefore rebuilt by the
    # recursive tree renderer below.
    #
    # This branch is intentionally replaced by the simpler
    # render_tree_node_with_prefix implementation.
    _ = relative_path

  return "".join(pieces)


def render_tree_node_with_prefix(
  node,
  version_base_url,
  prefix=None,
  parent_id="tree-root",
  level=0,
):
  """
  Recursive tree renderer which knows the complete file path.
  """

  if prefix is None:
    prefix = []

  pieces = []

  directories = sorted(
    key for key in node.keys()
    if key != "__files__"
  )

  files = sorted(node.get("__files__", []))

  for directory in directories:
    child = node[directory]

    if not tree_has_content(child):
      continue

    safe_id = re.sub(
      r"[^A-Za-z0-9_-]",
      "-",
      parent_id + "-" + directory,
    )

    child_html = render_tree_node_with_prefix(
      child,
      version_base_url,
      prefix=prefix + [directory],
      parent_id=safe_id,
      level=level + 1,
    )

    pieces.append(
      '<div class="tree-directory mb-1">'
      '<button '
      'class="btn btn-sm btn-toggle w-100 text-start" '
      'type="button" '
      'data-bs-toggle="collapse" '
      'data-bs-target="#'
      + html_escape(safe_id)
      + '" '
        'aria-expanded="'
      + ("true" if level == 0 else "false")
      + '">'
        '<span class="tree-icon">▸</span> '
      + html_escape(directory)
      + '</button>'
        '<div id="'
      + html_escape(safe_id)
      + '" class="collapse '
      + ("show" if level == 0 else "")
      + '">'
        '<div class="ms-3 ps-2 border-start">'
      + child_html
      + "</div>"
        "</div>"
        "</div>"
    )

  for filename in files:
    relative_path = "/".join(prefix + [filename])

    url = relative_url_from_version(
      version_base_url,
      relative_path.replace(
        Path(filename).suffix,
        ".html",
      ),
    )

    pieces.append(
      '<a class="tree-file d-block text-decoration-none '
      'small py-1 px-2 rounded" href="'
      + html_escape(url)
      + '">'
        '<span class="text-body-secondary me-1">•</span>'
      + html_escape(filename)
      + "</a>"
    )

  return "".join(pieces)


def find_relative_file_path(node, filename, prefix):
  """
  Retained for compatibility with the simpler renderer.
  """

  files = node.get("__files__", [])

  if filename in files:
    return "/".join(prefix + [filename])

  for directory, child in node.items():
    if directory == "__files__":
      continue

    result = find_relative_file_path(
      child,
      filename,
      prefix + [directory],
    )

    if result:
      return result

  return None


# ============================================================
# Source file rendering
# ============================================================

def render_source_file(
  source_root,
  relative_path,
  version_base_url,
):
  source_path = source_root / relative_path

  content = read_text_file(source_path)

  highlighted = highlight_source(
    relative_path,
    content,
  )

  escaped_title = html_escape(relative_path)

  page_title = (
    html_escape(Path(relative_path).name)
    + " – "
    + html_escape(REPO_NAME)
  )

  selector = build_version_selector(
    version_base_url,
  )

  tree = build_tree(source_root)

  sidebar = render_tree_node_with_prefix(
    tree,
    version_base_url,
  )

  body = (
    '<div class="container-fluid py-4">'
    '<div class="row g-4">'

    '<aside class="col-lg-3 col-xl-2">'
    + render_sidebar(
    selector,
    sidebar,
    version_base_url,
  )
    + "</aside>"

      '<main class="col-lg-9 col-xl-10">'

      '<div class="d-flex flex-wrap justify-content-between '
      'align-items-center gap-2 mb-3">'
      '<div>'
      '<div class="text-body-secondary small">'
      'Quelldatei'
      "</div>"
      '<h1 class="h4 mb-0">'
    + escaped_title
    + "</h1>"
      "</div>"
      '<a class="btn btn-outline-secondary btn-sm" href="'
    + html_escape(version_base_url + "index.html")
    + '">Projektübersicht</a>'
      "</div>"

      '<div class="source-wrapper">'
      '<table class="source-table">'
      '<tbody>'
    + render_numbered_source(
    highlighted,
  )
    + "</tbody>"
      "</table>"
      "</div>"

      "</main>"
      "</div>"
      "</div>"
  )

  return render_page(
    title=page_title,
    body=body,
    version_base_url=version_base_url,
  )


def render_numbered_source(highlighted):
  """
  Pygments produces one HTML fragment per source line.

  We wrap each line in a table row with a line-number anchor.
  """

  lines = highlighted.splitlines()

  rows = []

  for number, line in enumerate(lines, start=1):
    if not line:
      line = " "

    rows.append(
      '<tr id="line-'
      + str(number)
      + '">'
        '<td class="line-number">'
        '<a href="#line-'
      + str(number)
      + '">'
      + str(number)
      + "</a>"
        "</td>"
        '<td class="source-line"><code>'
      + line
      + "</code></td>"
        "</tr>"
    )

  if not rows:
    rows.append(
      '<tr>'
      '<td class="line-number">1</td>'
      '<td class="source-line"><code></code></td>'
      "</tr>"
    )

  return "".join(rows)


# ============================================================
# Search index
# ============================================================

def create_search_index(source_root):
  """
  Create a compact search index containing all Java files.

  The complete Java content is included because this allows
  client-side searching on GitHub Pages without a server.
  """

  files = []

  for path in sorted(source_root.rglob("*.java")):
    relative = path.relative_to(source_root)
    relative_string = normalize_path(relative)

    if is_excluded(relative_string):
      continue

    content = read_text_file(path)

    html_path = (
      str(Path(relative_string).with_suffix(".html"))
      .replace("\\", "/")
    )

    files.append(
      {
        "name": path.name,
        "path": relative_string,
        "url": html_path,
        "content": content,
      }
    )

  return files


def write_search_index(
  source_root,
  version_directory,
):
  index = create_search_index(source_root)

  path = version_directory / "search-index.js"

  content = (
    "window.SEARCH_INDEX = "
    + json.dumps(
    index,
    ensure_ascii=False,
    separators=(",", ":"),
  )
    + ";"
  )

  write_text(path, content)


