# ============================================================
# Version selector
# ============================================================

def load_versions():
  versions = [
    {
      "type": "main",
      "label": "main – aktuell",
      "url": site_base() + "index.html",
    }
  ]

  for pr in load_merged_prs():
    versions.append(
      {
        "type": "pr",
        "number": pr["number"],
        "label": (
          f"PR #{pr['number']} – "
          f"{pr['title']}"
        ),
        "mergedAt": pr["mergedAt"],
        "url": (
          site_base()
          + f"pr/{pr['number']}/index.html"
        ),
      }
    )

  return versions


def build_version_selector(version_base_url):
  versions = load_versions()

  current_url = version_base_url + "index.html"

  options = []

  for version in versions:
    selected = (
      " selected"
      if version["url"] == current_url
      else ""
    )

    label = version["label"]

    if version["type"] == "pr" and version.get("mergedAt"):
      label += " (" + version["mergedAt"][:10] + ")"

    options.append(
      '<option value="'
      + html_escape(version["url"])
      + '"'
      + selected
      + ">"
      + html_escape(label)
      + "</option>"
    )

  return (
    '<label for="versionSelector" '
    'class="form-label fw-semibold">'
    "Version"
    "</label>"
    '<select id="versionSelector" class="form-select">'
    + "".join(options)
    + "</select>"
  )


# ============================================================
# Sidebar
# ============================================================

def render_sidebar(
  selector,
  tree,
  version_base_url,
):
  parts = [
    '<div class="sticky-lg-top sidebar-top">',
    selector,
    render_search_box(version_base_url),
    '<div class="card shadow-sm">',
    '<div class="card-header fw-semibold">',
    'Projektstruktur',
    '</div>',
    '<div class="card-body p-2">',
    tree,
    '</div>',
    '</div>',
    '</div>',
  ]

  return "".join(parts)


