def render_readme(source_root):
  readme = source_root / "README.md"

  if not readme.exists():
    return ""

  content = read_text_file(readme)

  return (
    '<section class="mb-4">'
    '<h2 class="h4">README</h2>'
    '<div class="card shadow-sm">'
    '<div class="card-body markdown-body">'
    + render_markdown(content)
    + "</div>"
      "</div>"
      "</section>"
  )


def render_pom(source_root, version_base_url):
  pom = source_root / "pom.xml"

  if not pom.exists():
    return ""

  content = read_text_file(pom)

  return (
    '<section class="mb-4">'
    '<h2 class="h4">pom.xml</h2>'
    '<p class="text-body-secondary">'
    'Maven-Projektkonfiguration'
    "</p>"
    '<a class="btn btn-outline-primary btn-sm" href="'
    + html_escape(
    version_base_url + "pom.html"
  )
    + '">'
      "pom.xml anzeigen"
      "</a>"
      "</section>"
  )


def render_project_overview(
  source_root,
  version_type,
  version_base_url,
  pr=None,
):
  if version_type == "main":
    title = "Maven-Projekt"
    subtitle = (
      'Aktueller Stand des Projekts aus dem Branch '
      '<code>main</code>.'
    )
  else:
    title = (
      "PR #"
      + str(pr["number"])
      + " – "
      + html_escape(pr["title"])
    )

    subtitle = (
      "Projektstand nach dem Merge dieses Pull Requests."
    )

  selector = build_version_selector(
    version_base_url,
  )

  tree = build_tree(source_root)

  sidebar_tree = render_tree_node_with_prefix(
    tree,
    version_base_url,
  )

  sidebar = render_sidebar(
    selector,
    sidebar_tree,
    version_base_url,
  )

  search = render_search_box(
    version_base_url,
  )

  readme = render_readme(source_root)

  pom = render_pom(
    source_root,
    version_base_url,
  )

  parts = [
    '<div class="container-fluid py-4">',
    '<div class="row g-4">',

    '<aside class="col-lg-3 col-xl-2">',
    sidebar,
    '</aside>',

    '<main class="col-lg-9 col-xl-10">',

    '<div class="d-flex flex-wrap '
    'justify-content-between '
    'align-items-start gap-3 mb-4">',

    '<div>',
    '<div class="text-body-secondary small">',
    'Java / Maven',
    '</div>',

    '<h1 class="display-6 fw-semibold">',
    title,
    '</h1>',

    '<p class="lead">',
    subtitle,
    '</p>',

    '</div>',

    '<button '
    'id="themeToggle" '
    'class="btn btn-outline-secondary">',
    '☾ Dark Mode',
    '</button>',

    '</div>',

    readme,
    pom,
    search,

    '</main>',
    '</div>',
    '</div>',
  ]

  body = "".join(parts)

  return render_page(
    title=title,
    body=body,
    version_base_url=version_base_url,
  )


# ============================================================
# Page template
# ============================================================

def render_page(
  title,
  body,
  version_base_url,
):
  """
  Complete HTML document.

  IMPORTANT:
  This is intentionally NOT an f-string.

  JavaScript/CSS braces therefore require no escaping.
  """

  template = r"""<!doctype html>
<html lang="de">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">

    <title>__TITLE__</title>

    <link
        rel="stylesheet"
        href="__SITE_BASE__assets/bootstrap.min.css">

    <style>
        :root {
            --source-bg: #f8f9fa;
            --source-border: #dee2e6;
            --line-number: #6c757d;
        }

        [data-bs-theme="dark"] {
            --source-bg: #15171a;
            --source-border: #343a40;
            --line-number: #8b949e;
        }

        body {
            min-height: 100vh;
        }

        .sidebar-top {
            top: 1rem;
        }

        .tree-file {
            color: var(--bs-body-color);
        }

        .tree-file:hover {
            background: var(--bs-tertiary-bg);
        }

        .btn-toggle {
            color: var(--bs-body-color);
        }

        .btn-toggle:hover {
            background: var(--bs-tertiary-bg);
        }

        .tree-icon {
            display: inline-block;
            width: 1.2rem;
            transition: transform 0.15s ease;
        }

        .btn-toggle[aria-expanded="true"] .tree-icon {
            transform: rotate(90deg);
        }

        .source-wrapper {
            overflow-x: auto;
            border: 1px solid var(--source-border);
            border-radius: 0.5rem;
            background: var(--source-bg);
        }

        .source-table {
            width: 100%;
            border-collapse: collapse;
            font-family:
                ui-monospace,
                SFMono-Regular,
                Menlo,
                Monaco,
                Consolas,
                "Liberation Mono",
                "Courier New",
                monospace;
            font-size: 0.9rem;
        }

        .source-table tr:target {
            background: rgba(255, 193, 7, 0.18);
        }

        .line-number {
            width: 1%;
            min-width: 4.5rem;
            padding: 0 0.75rem;
            text-align: right;
            vertical-align: top;
            user-select: none;
            color: var(--line-number);
            border-right: 1px solid var(--source-border);
        }

        .line-number a {
            color: inherit;
            text-decoration: none;
        }

        .source-line {
            padding: 0 1rem;
            white-space: pre;
        }

        .source-line code {
            color: var(--bs-body-color);
        }

        .search-result {
            border-left: 4px solid var(--bs-primary);
        }

        .search-context {
            overflow-x: auto;
            white-space: pre;
            font-family:
                ui-monospace,
                SFMono-Regular,
                Menlo,
                Monaco,
                Consolas,
                monospace;
            font-size: 0.82rem;
        }

        .search-context .match-line {
            background: rgba(255, 193, 7, 0.2);
            font-weight: 600;
        }

        .search-context .context-line {
            color: var(--bs-secondary-color);
        }

        .markdown-body pre {
            padding: 1rem;
            border-radius: 0.5rem;
            overflow-x: auto;
            background: var(--bs-tertiary-bg);
        }

        .markdown-body code {
            word-break: break-word;
        }

        .markdown-body img {
            max-width: 100%;
            height: auto;
        }

        @media (max-width: 991.98px) {
            .sidebar-top {
                position: static !important;
            }
        }
    </style>
</head>

<body>
    __BODY__

    <script src="__SITE_BASE__assets/bootstrap.bundle.min.js"></script>
    <script src="__SITE_BASE__site.js"></script>

    <script>
        window.VERSION_BASE = "__VERSION_BASE__";
    </script>
</body>
</html>
"""

  result = template
  result = result.replace(
    "__TITLE__",
    html_escape(title),
  )
  result = result.replace(
    "__BODY__",
    body,
  )
  result = result.replace(
    "__SITE_BASE__",
    site_base(),
  )
  result = result.replace(
    "__VERSION_BASE__",
    version_base_url,
  )

  return result


# ============================================================
# Global JavaScript
# ============================================================

def write_site_javascript():
  """
  Write the JavaScript needed by all generated pages.

  It is still generated from this Python file; there is no
  JavaScript source file in the repository.
  """

  js = r"""
(function () {
    "use strict";

    /*
     * Version selector
     */
    const versionSelector =
        document.getElementById("versionSelector");

    if (versionSelector) {
        versionSelector.addEventListener("change", function () {
            const target = this.value;

            if (target) {
                window.location.href = target;
            }
        });
    }


    /*
     * Dark mode
     */
    const themeToggle =
        document.getElementById("themeToggle");

    function getPreferredTheme() {
        const stored =
            localStorage.getItem("pages-theme");

        if (stored === "light" || stored === "dark") {
            return stored;
        }

        if (
            window.matchMedia &&
            window.matchMedia(
                "(prefers-color-scheme: dark)"
            ).matches
        ) {
            return "dark";
        }

        return "light";
    }

    function updateThemeButton(theme) {
        if (!themeToggle) {
            return;
        }

        if (theme === "dark") {
            themeToggle.textContent = "☀ Light Mode";
        } else {
            themeToggle.textContent = "☾ Dark Mode";
        }
    }

    function setTheme(theme) {
        document.documentElement.setAttribute(
            "data-bs-theme",
            theme
        );

        localStorage.setItem(
            "pages-theme",
            theme
        );

        updateThemeButton(theme);
    }

    const initialTheme =
        getPreferredTheme();

    setTheme(initialTheme);

    if (themeToggle) {
        themeToggle.addEventListener(
            "click",
            function () {
                const current =
                    document.documentElement.getAttribute(
                        "data-bs-theme"
                    );

                setTheme(
                    current === "dark"
                        ? "light"
                        : "dark"
                );
            }
        );
    }


    /*
     * Search
     *
     * Search index is loaded dynamically.
     */
    const searchInput =
        document.getElementById("searchInput");

    const searchResults =
        document.getElementById("searchResults");

    const searchStatus =
        document.getElementById("searchStatus");

    const clearSearch =
        document.getElementById("clearSearch");

    if (!searchInput || !searchResults) {
        return;
    }

    const script =
        document.createElement("script");

    script.src =
        (window.VERSION_BASE || "") +
        "search-index.js";

    script.onload = function () {
        window.SEARCH_INDEX =
            window.SEARCH_INDEX || [];

        searchInput.disabled = false;

        if (searchStatus) {
            searchStatus.textContent =
                window.SEARCH_INDEX.length +
                " Java-Dateien geladen.";
        }
    };

    script.onerror = function () {
        if (searchStatus) {
            searchStatus.textContent =
                "Suchindex konnte nicht geladen werden.";
        }
    };

    searchInput.disabled = true;

    document.body.appendChild(script);


    /*
     * Escape HTML for search results.
     */
    function escapeHtml(value) {
        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    /*
     * Highlight search text.
     */
    function highlightText(text, query) {
        const escaped =
            escapeHtml(text);

        if (!query) {
            return escaped;
        }

        const escapedQuery =
            escapeHtml(query)
                .replace(
                    /[.*+?^${}()|[\]\\]/g,
                    "\\$&"
                );

        const regex =
            new RegExp(
                "(" + escapedQuery + ")",
                "gi"
            );

        return escaped.replace(
            regex,
            "<mark>$1</mark>"
        );
    }


    /*
     * Build one search result.
     */
    function buildResult(file, lineNumber, lines, query) {
        const start =
            Math.max(
                0,
                lineNumber - 1 - 2
            );

        const end =
            Math.min(
                lines.length,
                lineNumber + 2
            );

        let contextHtml = "";

        for (let i = start; i < end; i++) {
            const actualLine =
                i + 1;

            const className =
                actualLine === lineNumber
                    ? "match-line"
                    : "context-line";

            contextHtml +=
                '<div class="' +
                className +
                '">' +
                '<span class="text-body-secondary me-3">' +
                String(actualLine).padStart(5, " ") +
                "</span>" +
                highlightText(
                    lines[i],
                    query
                ) +
                "</div>";
        }

        const url =
            (window.VERSION_BASE || "") +
            file.url +
            "#line-" +
            lineNumber;

        return (
            '<div class="card search-result mb-3 shadow-sm">' +
                '<div class="card-body">' +

                    '<div class="d-flex justify-content-between ' +
                    'align-items-start gap-2 mb-2">' +

                        '<div>' +
                            '<a class="fw-semibold" href="' +
                            escapeHtml(url) +
                            '">' +
                            escapeHtml(file.path) +
                            "</a>" +
                        "</div>" +

                        '<span class="badge text-bg-secondary">' +
                            "Zeile " +
                            lineNumber +
                        "</span>" +

                    "</div>" +

                    '<div class="search-context">' +
                        contextHtml +
                    "</div>" +

                "</div>" +
            "</div>"
        );
    }


    /*
     * Perform search.
     */
    function performSearch() {
        const query =
            searchInput.value.trim();

        searchResults.innerHTML = "";

        if (!query) {
            if (searchStatus) {
                searchStatus.textContent =
                    window.SEARCH_INDEX
                        ? window.SEARCH_INDEX.length +
                          " Java-Dateien geladen."
                        : "";
            }

            return;
        }

        if (!window.SEARCH_INDEX) {
            if (searchStatus) {
                searchStatus.textContent =
                    "Suchindex wird noch geladen ...";
            }

            return;
        }

        const normalizedQuery =
            query.toLowerCase();

        let totalMatches = 0;
        let filesWithMatches = 0;

        const resultFragments = [];

        for (const file of window.SEARCH_INDEX) {
            const lines =
                String(file.content || "")
                    .split(/\r?\n/);

            const matchingLines = [];

            for (let i = 0; i < lines.length; i++) {
                if (
                    lines[i]
                        .toLowerCase()
                        .includes(normalizedQuery)
                ) {
                    matchingLines.push(i + 1);

                    if (
                        matchingLines.length >= 10
                    ) {
                        break;
                    }
                }
            }

            if (matchingLines.length === 0) {
                continue;
            }

            filesWithMatches++;

            for (const lineNumber of matchingLines) {
                totalMatches++;

                resultFragments.push(
                    buildResult(
                        file,
                        lineNumber,
                        lines,
                        query
                    )
                );
            }
        }

        if (searchStatus) {
            searchStatus.textContent =
                totalMatches +
                " Treffer in " +
                filesWithMatches +
                " Dateien.";
        }

        if (resultFragments.length === 0) {
            searchResults.innerHTML =
                '<div class="alert alert-secondary">' +
                "Keine Treffer." +
                "</div>";

            return;
        }

        searchResults.innerHTML =
            resultFragments.join("");
    }


    let searchTimer = null;

    searchInput.addEventListener(
        "input",
        function () {
            clearTimeout(searchTimer);

            searchTimer =
                setTimeout(
                    performSearch,
                    150
                );
        }
    );


    if (clearSearch) {
        clearSearch.addEventListener(
            "click",
            function () {
                searchInput.value = "";
                searchResults.innerHTML = "";

                if (searchStatus) {
                    searchStatus.textContent =
                        window.SEARCH_INDEX
                            ? window.SEARCH_INDEX.length +
                              " Java-Dateien geladen."
                            : "";
                }

                searchInput.focus();
            }
        );
    }

})();
"""

  write_text(
    SITE / "site.js",
    js,
  )


# ============================================================
# Version generation
# ============================================================

def generate_version(
  source_root,
  version_type,
  version_base_url,
  pr=None,
):
  """
  Generate one complete version of the project.
  """

  version_directory = (
    SITE
    / Path(version_base_url.lstrip("/"))
  )

  # For URLs such as /repo/, Path gives repo.
  # For /repo/pr/17/, it gives repo/pr/17.
  version_directory.mkdir(
    parents=True,
    exist_ok=True,
  )

  # --------------------------------------------------------
  # Search index
  # --------------------------------------------------------

  write_search_index(
    source_root,
    version_directory,
  )

  # --------------------------------------------------------
  # README / pom / source files
  # --------------------------------------------------------

  for path in source_root.rglob("*"):
    if not path.is_file():
      continue

    relative = path.relative_to(source_root)
    relative_string = normalize_path(relative)

    if is_excluded(relative_string):
      continue

    if not is_source_file(relative_string):
      continue

    output_path = (
      version_directory
      / Path(relative_string).with_suffix(".html")
    )

    page = render_source_file(
      source_root,
      relative_string,
      version_base_url,
    )

    write_text(
      output_path,
      page,
    )

  # --------------------------------------------------------
  # Project overview
  # --------------------------------------------------------

  overview = render_project_overview(
    source_root,
    version_type,
    version_base_url,
    pr=pr,
  )

  write_text(
    version_directory / "index.html",
    overview,
  )


# ============================================================
# Main generation
# ============================================================

def main():
  print("========================================")
  print("Generating GitHub Pages site")
  print("========================================")
  print(f"Repository: {REPO}")
  print(f"Repository name: {REPO_NAME}")
  print(f"Site base: {site_base()}")
  print()

  clean_site()
  copy_bootstrap()

  main_commit = get_main_commit()

  print(f"Main commit: {main_commit}")

  # --------------------------------------------------------
  # Current main
  # --------------------------------------------------------

  print()
  print("Generating main ...")

  main_source = ROOT / ".pages-main-source"

  if main_source.exists():
    shutil.rmtree(main_source)

  create_snapshot_from_commit(
    main_commit,
    main_source,
  )

  generate_version(
    source_root=main_source,
    version_type="main",
    version_base_url=version_base("main"),
  )

  # --------------------------------------------------------
  # Historical merged PRs
  # --------------------------------------------------------

  merged_prs = load_merged_prs()

  print()
  print(f"Found {len(merged_prs)} merged PR(s).")

  for pr in merged_prs:
    number = pr["number"]
    sha = pr["sha"]

    print(
      f"Generating PR #{number} "
      f"({sha[:12]}) ..."
    )

    pr_source = (
      ROOT
      / ".pages-pr-source"
      / str(number)
    )

    if pr_source.exists():
      shutil.rmtree(pr_source)

    create_snapshot_from_commit(
      sha,
      pr_source,
    )

    generate_version(
      source_root=pr_source,
      version_type="pr",
      version_base_url=version_base(
        "pr",
        number,
      ),
      pr=pr,
    )

  # --------------------------------------------------------
  # Global JavaScript
  # --------------------------------------------------------

  write_site_javascript()

  # --------------------------------------------------------
  # Safety check
  # --------------------------------------------------------

  forbidden = list(
    SITE.rglob("merged-prs.json")
  )

  if forbidden:
    raise RuntimeError(
      "ERROR: merged-prs.json would be published: "
      + ", ".join(str(p) for p in forbidden)
    )

  # Search index files are intentional.
  # merged-prs.json must never be inside _site.

  # --------------------------------------------------------
  # Cleanup temporary snapshots
  # --------------------------------------------------------

  for temporary in [
    ROOT / ".pages-main-source",
    ROOT / ".pages-pr-source",
  ]:
    if temporary.exists():
      shutil.rmtree(temporary)

  print()
  print("========================================")
  print("Pages site successfully generated.")
  print("========================================")
  print(f"Output: {SITE}")


if __name__ == "__main__":
  main()
